import os
import textwrap
from collections import Counter
from dataclasses import dataclass
from tempfile import NamedTemporaryFile
from typing import Dict, Iterable, List, Tuple

import viktor as vkt


# -----------------------------
# Helpers
# -----------------------------


@dataclass(frozen=True)
class CountResult:
    schema: str
    total_in_scope: int
    total_after_filters: int
    counts_after_filters: Dict[str, int]
    distinct_types_after_filters: int


def _require_ifcopenshell():
    """Import ifcopenshell only when needed, so the app can still load without it."""
    try:
        import ifcopenshell  # noqa: F401
    except ImportError as e:
        raise vkt.UserError(
            "Python package 'ifcopenshell' is not available in this environment. "
            "Add it to requirements.txt (e.g. ifcopenshell==0.8.*) and redeploy the app."
        ) from e


def _load_ifc_model(viktor_file: vkt.File):
    """Load IFC into ifcopenshell.

    Tries in-memory parsing first (fast, no disk IO). If that fails, falls back to a temporary file.
    """
    _require_ifcopenshell()
    import ifcopenshell

    raw = viktor_file.getvalue()

    # 1) Try in-memory
    try:
        if isinstance(raw, bytes):
            try:
                ifc_text = raw.decode("utf-8")
            except UnicodeDecodeError:
                ifc_text = raw.decode("latin-1")
        else:
            ifc_text = str(raw)
        return ifcopenshell.file.from_string(ifc_text)
    except Exception:
        pass

    # 2) Fallback: write temp file and open
    tmp_path = None
    try:
        with NamedTemporaryFile(suffix=".ifc", delete=False) as tmp:
            tmp_path = tmp.name
            if isinstance(raw, str):
                raw = raw.encode("utf-8")
            tmp.write(raw)
        return ifcopenshell.open(tmp_path)
    finally:
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except OSError:
                # Best-effort cleanup
                pass


def _iter_entities(model, scope: str) -> Iterable:
    """Return an iterable of IFC entities to count."""
    if scope == "Physical elements (IfcElement, excl. IfcOpeningElement)":
        elems = model.by_type("IfcElement")
        return (e for e in elems if not e.is_a("IfcOpeningElement"))

    if scope == "Physical elements (IfcElement, incl. IfcOpeningElement)":
        return model.by_type("IfcElement")

    if scope == "All products (IfcProduct, incl. spatial structure)":
        return model.by_type("IfcProduct")

    if scope == "All rooted objects (IfcRoot)":
        # All objects with GlobalId (includes project, site, etc.)
        return model.by_type("IfcRoot")

    # Fallback
    return model.by_type("IfcElement")


def _apply_type_filters(
    counts: Counter,
    type_filter: str,
    case_sensitive: bool,
    min_count: int,
) -> Dict[str, int]:
    filt = type_filter or ""
    if not case_sensitive:
        filt = filt.lower()

    out: Dict[str, int] = {}
    for ifc_class, cnt in counts.items():
        if cnt < min_count:
            continue
        name_cmp = ifc_class if case_sensitive else ifc_class.lower()
        if filt and filt not in name_cmp:
            continue
        out[ifc_class] = int(cnt)

    return out


def _sorted_rows(counts: Dict[str, int], sort_by: str) -> List[List]:
    items = list(counts.items())
    if sort_by == "Count (desc)":
        items.sort(key=lambda kv: (kv[1], kv[0]), reverse=True)
    elif sort_by == "Count (asc)":
        items.sort(key=lambda kv: (kv[1], kv[0]))
    else:  # "Type (A→Z)"
        items.sort(key=lambda kv: kv[0])

    return [[k, v] for k, v in items]


def _compute_counts(params) -> CountResult:
    if not params.main.inputs.ifc_file:
        raise vkt.UserError("Upload an IFC file first.")

    model = _load_ifc_model(params.main.inputs.ifc_file.file)

    # Schema (e.g. IFC2X3 / IFC4 / IFC4X3)
    schema = getattr(model, "schema", "(unknown)")

    entities = list(_iter_entities(model, params.main.inputs.scope))
    total_in_scope = len(entities)

    counts = Counter(e.is_a() for e in entities)

    counts_after_filters = _apply_type_filters(
        counts=counts,
        type_filter=params.main.inputs.type_filter,
        case_sensitive=bool(params.main.inputs.case_sensitive),
        min_count=int(params.main.inputs.min_count or 1),
    )

    total_after_filters = int(sum(counts_after_filters.values()))

    return CountResult(
        schema=schema,
        total_in_scope=total_in_scope,
        total_after_filters=total_after_filters,
        counts_after_filters=counts_after_filters,
        distinct_types_after_filters=len(counts_after_filters),
    )


# -----------------------------
# Viktor app
# -----------------------------


SCOPE_OPTIONS = [
    "Physical elements (IfcElement, excl. IfcOpeningElement)",
    "Physical elements (IfcElement, incl. IfcOpeningElement)",
    "All products (IfcProduct, incl. spatial structure)",
    "All rooted objects (IfcRoot)",
]

SORT_OPTIONS = [
    "Count (desc)",
    "Count (asc)",
    "Type (A→Z)",
]


class Parametrization(vkt.Parametrization):
    main = vkt.Page("Model contents", views=["ifc_view", "model_summary", "element_count_table"])

    main.inputs = vkt.Section("Inputs")
    main.inputs.intro = vkt.Text(
        textwrap.dedent(
            """\
            # IFC Element Count by Category

            Upload an IFC file to get a quick overview of the model contents.

            **Table features**
            - Count per IFC class (e.g. `IfcWall`, `IfcDoor`)
            - Built-in sorting and filtering in the table view (column headers / filter controls)
            - Optional extra filtering via the inputs below
            """
        )
    )

    main.inputs.ifc_file = vkt.FileField("IFC file")

    main.inputs.scope = vkt.OptionField(
        "Count scope",
        options=SCOPE_OPTIONS,
        default="Physical elements (IfcElement, excl. IfcOpeningElement)",
        description="Controls which objects are included in the counting.",
    )

    main.inputs.type_filter = vkt.TextField(
        "Type name contains",
        default="",
        description="Example: 'Wall' will match IfcWall, IfcWallStandardCase, etc.",
    )
    main.inputs.case_sensitive = vkt.BooleanField("Case sensitive filter", default=False)

    main.inputs.min_count = vkt.IntegerField(
        "Minimum count",
        default=1,
        min=1,
        description="Hide categories with a count smaller than this value.",
    )

    main.inputs.sort_by = vkt.OptionField("Default sorting", options=SORT_OPTIONS, default="Count (desc)")


class Controller(vkt.Controller):
    parametrization = Parametrization(width=55)

    @vkt.IFCView("IFC viewer")
    def ifc_view(self, params, **kwargs):
        if not params.main.inputs.ifc_file:
            raise vkt.UserError("Upload an IFC file first.")
        return vkt.IFCResult(params.main.inputs.ifc_file.file)

    @vkt.DataView("Summary")
    def model_summary(self, params, **kwargs):
        res = _compute_counts(params)

        # Top 5 types
        top5 = sorted(res.counts_after_filters.items(), key=lambda kv: (kv[1], kv[0]), reverse=True)[:5]
        top5_items = [vkt.DataItem(k, v) for k, v in top5] if top5 else [vkt.DataItem("(none)", "")]

        data = vkt.DataGroup(
            vkt.DataItem("IFC schema", res.schema),
            vkt.DataItem("Total elements (in selected scope)", res.total_in_scope),
            vkt.DataItem("Total elements (after filters)", res.total_after_filters),
            vkt.DataItem("Distinct IFC classes (after filters)", res.distinct_types_after_filters),
            vkt.DataItem("Top 5 classes (after filters)", "", subgroup=vkt.DataGroup(*top5_items)),
        )
        return vkt.DataResult(data)

    @vkt.TableView("Element count by IFC class", duration_guess=3)
    def element_count_table(self, params, **kwargs):
        res = _compute_counts(params)

        rows = _sorted_rows(res.counts_after_filters, params.main.inputs.sort_by)
        return vkt.TableResult(
            rows,
            column_headers=["IFC class", "Count"],
            enable_sorting_and_filtering=True,
        )
